INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q431806', 'Arauco War', 'The Arauco War was a long-running conflict between colonial Spaniards and the Mapuche people, mostly fought in the Araucanía region of Chile. The conflict began at first as a reaction by the Mapuche to the Spanish conquerors attempting to establish cities and force the natives into servitude.', 1546, NULL, NULL, 1609, NULL, NULL, 'year', '1546–1609', 62, 'https://en.wikipedia.org/wiki/Arauco_War'),
  ('Q1617667', 'Battle of Mataquito', 'The Battle of Mataquito was fought in the Arauco War on April 30, 1557, between the forces of the Spanish governor, Francisco de Villagra, and Mapuche headed by their toqui Lautaro. It was a surprise attack, carried out at dawn, on Lautaro''s fortified camp between a wooded mountain and the shore of the Mataquito River.', 1557, 4, 30, NULL, NULL, NULL, 'day', '30 April 1557', 37, 'https://en.wikipedia.org/wiki/Battle_of_Mataquito'),
  ('Q2339158', 'Battle of Millarapue', 'The Battle of Millarapue that occurred November 30, 1557 was intended by the Toqui Caupolicán as a Mapuche ambush of the Spanish army of García Hurtado de Mendoza that resulted in a Spanish victory when the ambush failed.', 1557, 11, 30, NULL, NULL, NULL, 'day', '30 November 1557', 37, 'https://en.wikipedia.org/wiki/Battle_of_Millarapue'),
  ('Q1348911', '1575 Valdivia earthquake', 'The 1575 Valdivia earthquake occurred at 14:30 local time on December 16. It had an estimated magnitude of 8.5 of on the surface-wave magnitude scale and an estimated magnitude of 9.0+ on the Moment magnitude scale and led to the flood of Valdivia, Chile.', 1575, 12, 16, NULL, NULL, NULL, 'day', '16 December 1575', 45, 'https://en.wikipedia.org/wiki/1575_Valdivia_earthquake'),
  ('Q4552629', '1730 Valparaíso earthquake', 'The 1730 Valparaíso earthquake occurred at 04:45 local time (08:45 UTC) on July 8. It had an estimated magnitude of 9.1–9.3 and triggered a major tsunami with an estimated magnitude of Mt 8.75, that inundated the lower parts of Valparaíso.', 1730, NULL, NULL, NULL, NULL, NULL, 'year', '1730', 39, 'https://en.wikipedia.org/wiki/1730_Valpara%C3%ADso_earthquake'),
  ('Q246652', 'Battle of Tacuarí', 'The Battle of Tacuarí (9 March 1811) was a battle in Southern Paraguay between forces sent by the Junta of Buenos Aires under the command of General Manuel Belgrano, and Paraguayan troops under Colonel Manuel Atanasio Cabañas, at the service of the Council of Regency.', 1811, 3, 9, NULL, NULL, NULL, 'day', '9 March 1811', 39, 'https://en.wikipedia.org/wiki/Battle_of_Tacuar%C3%AD'),
  ('Q1072889', 'Chilean War of Independence', 'The Chilean War of Independence (Spanish: Guerra de la Independencia de Chile, ''War of Independence of Chile'') was a military and political event that allowed the emancipation of Chile from the Spanish Monarchy, ending the colonial period and initiating the formation of an independent republic. It developed in the context of the Spanish American Wars of independence, a military and political process that began after the formation of self-government juntas in the Spanish-American colonies, in response to the capture of King Ferdinand VII of Spain by Napoleonic forces in 1808.', 1812, NULL, NULL, NULL, NULL, NULL, 'year', '1812', 57, 'https://en.wikipedia.org/wiki/Chilean_War_of_Independence'),
  ('Q1310755', 'Battle of Rancagua', 'The Battle of Rancagua, also known in Chile as the Disaster of Rancagua, occurred on October 1, 1814, to October 2, 1814, when the Spanish Army under the command of Mariano Osorio defeated the Chilean forces led by Bernardo O’Higgins. This put an end to the Chilean Patria Vieja and it was the decisive step of the Spanish military Reconquest of Chile.', 1814, 10, 2, NULL, NULL, NULL, 'day', '2 October 1814', 50, 'https://en.wikipedia.org/wiki/Battle_of_Rancagua'),
  ('Q1425658', 'Battle of Chacabuco', 'The Battle of Chacabuco, fought during the Chilean War of Independence, took place on February 12, 1817. The Army of the Andes, from the United Provinces of the Río de la Plata and led by Captain–General José de San Martín, defeated a Spanish force commanded by Rafael Maroto.', 1817, 2, 12, NULL, NULL, NULL, 'day', '12 February 1817', 58, 'https://en.wikipedia.org/wiki/Battle_of_Chacabuco'),
  ('Q1073849', 'Battle of Maipú', 'The Battle of Maipú (Spanish: Batalla de Maipú) was fought near Santiago, Chile on 5 April 1818, between South American rebels and Spanish royalists, during the Chilean War of Independence. The Patriot rebels led by Argentine general José de San Martín effectively destroyed the Spanish forces commanded by General Mariano Osorio, and completed the independence of the core area of Chile from Spanish domination.', 1818, 4, 5, NULL, NULL, NULL, 'day', '5 April 1818', 60, 'https://en.wikipedia.org/wiki/Battle_of_Maip%C3%BA'),
  ('Q5098735', 'Chilean Civil War of 1829-1830', 'The Chilean Civil War of 1829–1830 (Spanish: Guerra Civil de 1829–1830), or the First Chilean Civil War, was a civil war in Chile fought between conservative Pelucones and liberal Pipiolos forces over the constitutional regime in force. This conflict ended with the defeat of the liberal forces and the approval of a new constitution in 1833, that was in force until 1925.', 1829, NULL, NULL, 1830, NULL, NULL, 'year', '1829–1830', 37, 'https://en.wikipedia.org/wiki/Chilean_Civil_War_of_1829%E2%80%931830'),
  ('Q2068462', '1834 Concepción earthquake', 'The 1835 Concepción earthquake was an earthquake that occurred near the neighboring cities of Concepción and Talcahuano in Chile on 20 February at 11:30 local time (15:30 UTC), and had an estimated magnitude of about 8.5 Mw. The earthquake triggered a tsunami which caused the destruction of Talcahuano.', 1835, NULL, NULL, NULL, NULL, NULL, 'year', '1835', 41, 'https://en.wikipedia.org/wiki/1835_Concepci%C3%B3n_earthquake'),
  ('Q601811', 'War of the Confederation', 'The War of the Confederation (Spanish: Guerra de la Confederación) was a military confrontation waged by the United Restoration Army, the alliance of the land and naval forces of Chile and the Restoration Army of Peru, formed in 1836 by Peruvian soldiers opposed to the confederation, and the Argentine Confederation against the Peru–Bolivian Confederation between 1836 and 1839. As a result of the Salaverry-Santa Cruz War, the Peru–Bolivian Confederation was created by General Andrés de Santa Cruz, which caused a power struggle in southern South America, with Chile and the Argentine…', 1836, NULL, NULL, 1839, 8, 15, 'year', '1836 – 15 August 1839', 57, 'https://en.wikipedia.org/wiki/War_of_the_Confederation'),
  ('Q4554827', '1851 Chilean Revolution', 'The Revolution of 1851 was an attempt by Chilean liberals to overthrow the conservative government of president Manuel Montt and repeal the Chilean Constitution of 1833. After various battles and sieges, by late December 1851 government forces had subdued the revolutionaries.', 1851, 12, 31, 1851, 12, 31, 'day', '31 December 1851', 26, 'https://en.wikipedia.org/wiki/1851_Chilean_revolution'),
  ('Q2422135', 'occupation of Araucanía', 'The Occupation of Araucanía or Pacification of Araucanía (1861–1883) was a series of military campaigns, agreements and penetrations by the Chilean military and settlers into Mapuche territory which led to the incorporation of Araucanía into Chilean national territory. Pacification of Araucanía was the expression used by the Chilean authorities for this process.', 1861, NULL, NULL, 1883, NULL, NULL, 'year', '1861–1883', 53, 'https://en.wikipedia.org/wiki/Occupation_of_Araucan%C3%ADa'),
  ('Q977868', 'Church of the Company Fire', 'The Iglesia de la Compañía de Jesús Fire (8 December 1863) was a mass casualty event in Santiago, Chile. It is the deadliest fire known to have occurred in the city, one of the deadliest single-building fires in world history and one of the deadliest-ever fires within a religious site.', 1863, 12, 8, NULL, NULL, NULL, 'day', '8 December 1863', 43, 'https://en.wikipedia.org/wiki/Iglesia_de_la_Compa%C3%B1%C3%ADa_Fire'),
  ('Q660025', 'Battle of Papudo', 'The Naval Battle of Papudo was a naval engagement fought between Spanish and Chilean forces on November 26, 1865, during the Chincha Islands War. It was fought 55 miles (48 nmi; 89 km) north of Valparaíso, Chile, near the coastal town of Papudo.', 1865, 11, 26, NULL, NULL, NULL, 'day', '26 November 1865', 39, 'https://en.wikipedia.org/wiki/Battle_of_Papudo'),
  ('Q21888117', 'Tratado de 1874 entre Bolivia y Chile', 'The Boundary Treaty of 1874 between Chile and Bolivia, also called the Treaty of Sucre, was signed in Sucre on August 6, 1874, by the Bolivian Minister of Foreign Affairs Mariano Baptista and the Chilean plenipotentiary minister Carlos Walker Martínez. It superseded the Boundary Treaty of 1866 between Chile and Bolivia, establishing the border between both countries at the 24° South parallel from the Pacific Ocean to the eastern border of Chile.', 1874, NULL, NULL, NULL, NULL, NULL, 'year', '1874', 34, 'https://en.wikipedia.org/wiki/Boundary_Treaty_of_1874_between_Chile_and_Bolivia'),
  ('Q152004', 'War of the Pacific', 'The War of the Pacific (Spanish: Guerra del Pacífico), also known by multiple other names, was a war between Chile and a Bolivian–Peruvian alliance from 1879 to 1884. Fought over Chilean claims on coastal Bolivian territory in the Atacama Desert, the war ended with victory for Chile, which gained a significant amount of resource-rich territory from Peru and Bolivia.', 1879, 4, 5, 1884, 4, 4, 'day', '5 April 1879 – 4 April 1884', 79, 'https://en.wikipedia.org/wiki/War_of_the_Pacific'),
  ('Q3320910', 'Battle of Topeter', 'The Battle of Topáter, or Battle of Calama, was fought on March 23, 1879, between Chile and Bolivia. It was the first battle of the War of the Pacific.', 1879, 3, 23, NULL, NULL, NULL, 'day', '23 March 1879', 39, 'https://en.wikipedia.org/wiki/Battle_of_Top%C3%A1ter'),
  ('Q3373123', 'Battle of Pisagua', 'The Battle of Pisagua ("Desembarco y combate de Pisagua"), was a landing operation of the War of the Pacific, fought on November 2, 1879, between Chile and the combined forces of Bolivia and Peru. The Chilean army commanded by Erasmo Escala, supported by the Chilean Fleet, launched an amphibious assault on the port of Pisagua and successfully drove the defending Bolivian-Peruvian forces, led by Gen.', 1879, 11, 2, NULL, NULL, NULL, 'day', '2 November 1879', 41, 'https://en.wikipedia.org/wiki/Battle_of_Pisagua'),
  ('Q2887897', 'Battle of Arica', 'The Battle of Arica, also known as Assault and Capture of Cape Arica, was a battle in the War of the Pacific. It was fought on 7 June 1880, between the forces of Chile and Peru.', 1880, 6, 7, NULL, NULL, NULL, 'day', '7 June 1880', 43, 'https://en.wikipedia.org/wiki/Battle_of_Arica'),
  ('Q4135525', 'Selknam genocide', 'The Selkʼnam genocide was the systematic extermination of the Selkʼnam people, one of the four indigenous peoples of Tierra del Fuego archipelago, in the late 19th and early 20th centuries. Historians estimate that the genocide spanned a period of between ten and twenty years, and resulted in the decline of the Selkʼnam population from approximately 4,000 people during the 1880s to a few hundred by the early 1900s.', 1880, NULL, NULL, 1910, NULL, NULL, 'year', '1880–1910', 48, 'https://en.wikipedia.org/wiki/Selk%CA%BCnam_genocide'),
  ('Q940076', 'Boundary treaty of 1881 between Chile and Argentina', 'The Boundary Treaty of 1881 (Spanish: Tratado de Límites de 1881) between Argentina and Chile was signed on 23 July 1881 in Buenos Aires by Bernardo de Irigoyen, for Argentina, and Francisco de Borja Echeverría, for Chile, with the aim of establishing a precise border between the two countries based on the uti possidetis juris principle. Despite dividing largely unexplored lands, the treaty laid the groundwork for nearly all of Chile''s and Argentina''s 5600 km current border.', 1881, 7, 23, NULL, NULL, NULL, 'day', '23 July 1881', 41, 'https://en.wikipedia.org/wiki/Boundary_Treaty_of_1881_between_Chile_and_Argentina'),
  ('Q1475005', 'Treaty of Ancón', 'The Treaty of Ancón was a peace treaty signed by Chile and Peru on 20 October 1883, in Ancón, near Lima. It was intended to settle the two nations'' remaining territorial differences at the conclusion of their involvement in the War of the Pacific and to stabilise post-bellum relations between them.', 1883, NULL, NULL, NULL, NULL, NULL, 'year', '1883', 47, 'https://en.wikipedia.org/wiki/Treaty_of_Anc%C3%B3n'),
  ('Q580021', 'Battle of Caldera Bay', 'The Battle of Caldera Bay, or the Sinking of Blanco Encalada, was a naval engagement fought in the Caldera Bay during the 1891 Chilean Civil War between Balmacedist and Congressional naval forces on 23 April 1891. It involved two Balmacedist torpedo boats of the Almirante Lynch-class, and the Congressional armored frigate Blanco Encalada.', 1891, 4, 23, NULL, NULL, NULL, 'day', '23 April 1891', 34, 'https://en.wikipedia.org/wiki/Battle_of_Caldera_Bay'),
  ('Q2888327', 'Battle of Concón', 'The Battle of Concón was fought between the forces of the Congress of Chile and loyalists of President Jose Manuel Balmaceda. In mid-August 1891 the rebel forces were embarked at Iquique, numbering in all about 9,000 men, and sailed for the south.', 1891, 8, 21, NULL, NULL, NULL, 'day', '21 August 1891', 34, 'https://en.wikipedia.org/wiki/Battle_of_Conc%C3%B3n'),
  ('Q2889617', 'Battle of Placilla', 'The Battle of Placilla was an engagement fought during the Chilean Civil War of 1891 between Balmacedist and Congressional forces on 28 August 1891. The Congressist victory in the battle effectively determined the outcome of the war.', 1891, 8, 28, NULL, NULL, NULL, 'day', '28 August 1891', 34, 'https://en.wikipedia.org/wiki/Battle_of_Placilla'),
  ('Q7123137', 'Pacts of May', 'The Pacts of May (Spanish: Pactos de Mayo) are four protocols signed in Santiago de Chile by Chile and Argentina on 28 May 1902 in order to extend their relations and resolve its territorial disputes. The disputes had led both countries to increase their military budgets and run an arms race in the 1890s.', 1902, 5, 28, NULL, NULL, NULL, 'day', '28 May 1902', 37, 'https://en.wikipedia.org/wiki/Pacts_of_May'),
  ('Q473661', 'Treaty of Peace and love', 'The Treaty of Peace and Friendship of 1904 between Chile and Bolivia was signed in Santiago de Chile on 20 October 1904, to delineate the boundary through 96 specified points between Cerro Zapaleri and Cerro Chipe and to regulate the relations between the two countries 20 years after the end of the War of the Pacific. The Bolivia–Chile boundary is about 861 kilometres (535 mi) long and is demarcated by pillars in the Andes.', 1904, 10, 20, NULL, NULL, NULL, 'day', '20 October 1904', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Peace_and_Friendship_(1904)'),
  ('Q4558563', '1906 Valparaíso earthquake', 'The 1906 Valparaíso earthquake occurred on August 16 at 19:55 local time. Its epicenter was offshore of the Valparaíso Region of Chile, and its magnitude was estimated at 8.2 Mw.', 1906, 8, 16, NULL, NULL, NULL, 'day', '16 August 1906', 43, 'https://en.wikipedia.org/wiki/1906_Valpara%C3%ADso_earthquake'),
  ('Q583937', 'Santa María School massacre', 'The Santa María School massacre (Spanish: Matanza de la Escuela Santa María de Iquique) was a massacre of striking workers, mostly saltpeter works (nitrate) miners, along with their wives and children, committed by the Chilean Army in Iquique, Chile, on December 21, 1907. The number of victims is undetermined but is estimated to be over 2,000.', 1907, 12, 22, NULL, NULL, NULL, 'day', '22 December 1907', 55, 'https://en.wikipedia.org/wiki/Santa_Mar%C3%ADa_School_massacre'),
  ('Q4871836', 'Battle of Más a Tierra', 'The Battle of Más a Tierra was a World War I sea battle fought on 14 March 1915, near the Chilean island of Más a Tierra, between a British squadron and a German light cruiser. The battle saw the last remnant of the German East Asia Squadron destroyed, when SMS Dresden was cornered and scuttled in Cumberland Bay.', 1915, 3, 14, NULL, NULL, NULL, 'day', '14 March 1915', 47, 'https://en.wikipedia.org/wiki/Battle_of_M%C3%A1s_a_Tierra'),
  ('Q4561707', '1925 Chilean coup d''état', 'The Chilean coup d''état of 1925 took place on January 23, 1925, when the Chilean military overthrew the September Junta. Led by Colonel Marmaduque Grove, the troops arrested the Junta''s President, General Luis Altamirano, and then handed the power to General Pedro Dartnell as interim President.', 1925, 1, 23, NULL, NULL, NULL, 'day', '23 January 1925', 34, 'https://en.wikipedia.org/wiki/1925_Chilean_coup_d''%C3%A9tat'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q2990714', 'Treaty of Lima', 'The Treaty of Lima was a boundary treaty signed on June 3, 1929. The agreement put an end to the territorial dispute regarding the provinces of Tacna and Arica, which had been administered by Chile since 1883.', 1929, 6, 3, NULL, NULL, NULL, 'day', '3 June 1929', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Lima_(1929)'),
  ('Q4121073', 'Chilean naval mutiny of 1931', 'The Chilean naval mutiny of 1931 (Spanish: Sublevación de la Escuadra) was a violent rebellion of Chilean Navy enlisted men against the government of Vice President Manuel Trucco.', 1931, 9, NULL, 1931, 9, 7, 'month', 'September 1931 – 7 September 1931', 37, 'https://en.wikipedia.org/wiki/Chilean_naval_mutiny_of_1931'),
  ('Q2834857', '1949 Tierra del Fuego earthquake', 'The 1949 Tierra del Fuego earthquakes occurred slightly more than eight hours apart on 17 December. Their epicenters were located in the east of the Chilean Tierra del Fuego Province, close to the Argentine border on the island of Tierra del Fuego.', 1949, 12, 17, NULL, NULL, NULL, 'day', '17 December 1949', 37, 'https://en.wikipedia.org/wiki/1949_Tierra_del_Fuego_earthquakes'),
  ('Q212618', '1960 Valdivia earthquake', 'On 22 May 1960, an earthquake and tsunami occurred in Chile, devastating the city of Valdivia. Most studies have placed it at 9.4–9.6 on the moment magnitude scale, making it the strongest earthquake ever recorded, while some studies have placed the magnitude lower than 9.4.', 1960, 5, 21, NULL, NULL, NULL, 'day', '21 May 1960', 75, 'https://en.wikipedia.org/wiki/1960_Valdivia_earthquake'),
  ('Q3067075', '1960 Concepción earthquake', 'The 1960 Concepción earthquakes were a succession of three destructive earthquakes that happened between 21 and 22 May 1960. They formed part of the foreshock sequence for the 1960 Valdivia earthquake, the largest recorded earthquake in history.', 1960, 5, 21, NULL, NULL, NULL, 'day', '21 May 1960', 37, 'https://en.wikipedia.org/wiki/1960_Concepci%C3%B3n_earthquakes'),
  ('Q737967', '1972 Andes flight disaster', 'Uruguayan Air Force Flight 571 was the chartered flight of a Fairchild FH-227D from Montevideo, Uruguay, to Santiago, Chile, that crashed in the Andes mountains in Argentina on 13 October 1972. The accident and subsequent survival became known as both the Andes flight disaster (Tragedia de los Andes, literally Tragedy of the Andes) and the Miracle of the Andes (Milagro de los Andes).', 1972, 10, 13, NULL, NULL, NULL, 'day', '13 October 1972', 69, 'https://en.wikipedia.org/wiki/Uruguayan_Air_Force_Flight_571'),
  ('Q856670', '1973 Chilean coup d''état', 'The 1973 Chilean coup d''état (Spanish: Golpe de Estado en Chile de 1973) was a military overthrow of the socialist president of Chile Salvador Allende and his Popular Unity coalition government. Allende, who was the first Marxist to be democratically elected president in a Latin American liberal democracy, faced significant social unrest and political tension with the opposition-controlled National Congress of Chile.', 1973, 9, 11, NULL, NULL, NULL, 'day', '11 September 1973', 75, 'https://en.wikipedia.org/wiki/1973_Chilean_coup_d''%C3%A9tat'),
  ('Q5657104', 'Charaña Accords', 'The Charaña Accord, also known as the Hug of Charaña or the Act of Charaña, is the name given to an unrealized treaty that was discussed between the dictators of Bolivia and Chile, Hugo Banzer and Augusto Pinochet respectively. These discussions took place mostly on the Bolivian train station of Charaña on February 8, 1975, and included the brief reestablishment of diplomatic relations between the two nations which had been severed on 1962 because of the Atacama border dispute which was to be solved via a Chilean proposal for the exchange of territories between Bolivia and Chile, with the…', 1975, 2, 8, NULL, NULL, NULL, 'day', '8 February 1975', 30, 'https://en.wikipedia.org/wiki/Chara%C3%B1a_Accord'),
  ('Q521570', 'Chilean national consultation', 'A national consultation on President Augusto Pinochet''s political program was held throughout Chile on 4 January 1978. After being accused of human rights violations by the United Nations, Pinochet announced a national vote to confirm support for his policies.', 1978, 1, 4, NULL, NULL, NULL, 'day', '4 January 1978', 39, 'https://en.wikipedia.org/wiki/1978_Chilean_political_programme_referendum'),
  ('Q3240757', '1985 Santiago jimin', 'A megathrust earthquake measuring 8.0 Mw struck just offshore the Greater Valparaíso area of Central Chile on 3 March 1985. The event followed a ten-day period of moderate and non-destructive foreshocks and left at least 177 people dead and about 2,500 injured.', 1985, 3, 3, NULL, NULL, NULL, 'day', '3 March 1985', 47, 'https://en.wikipedia.org/wiki/1985_Algarrobo_earthquake'),
  ('Q3454843', 'Chilean national plebiscite, 1988', 'A referendum on whether Augusto Pinochet, the head of a military dictatorship, should become president for eight years under resumed civilian rule was held in Chile on 5 October 1988. The "No" side won with 56% of the vote, marking the end of Pinochet''s 16+1⁄2-year rule.', 1988, 10, 5, NULL, NULL, NULL, 'day', '5 October 1988', 51, 'https://en.wikipedia.org/wiki/1988_Chilean_presidential_referendum'),
  ('Q4604922', '2005 Tarapacá earthquake', 'On June 13, 2005, at 22:44:33 CLT, a Mw 7.8 earthquake struck near Mamiña, in northern Chile about 125 km east-northeast of Iquique, affecting the Tarapacá and Arica y Parinacota Regions, as well as adjacent parts of Bolivia and Peru. It had a maximum felt intensity of IX (Violent) to X (Extreme) on the Mercalli intensity scale.', 2005, 6, 13, NULL, NULL, NULL, 'day', '13 June 2005', 34, 'https://en.wikipedia.org/wiki/2005_Tarapac%C3%A1_earthquake'),
  ('Q3274804', '2006 student protests in Chile', 'The 2006 student protests in Chile (also known as the Penguins'' Revolution or The March of the Penguins, because of the students'' uniform) were a series of ongoing student voice protests carried out by high school students across Chile (from late April to early June 2006) against the privatization of the Chilean education system, implemented by dictator Augusto Pinochet in the 1970s. The protests peaked on May 30, when 790,000 students adhered to strikes and protests throughout the country, becoming Chile''s largest student demonstration in three decades and the first political crisis of…', 2006, NULL, NULL, NULL, NULL, NULL, 'year', '2006', 41, 'https://en.wikipedia.org/wiki/2006_student_protests_in_Chile'),
  ('Q4607867', '2007 Aisén Fjord earthquake', 'The 2007 Aysén Fjord earthquakes occurred in Aisén Fjord, Chile from January 22 – April 22. The biggest occurred at 1:53 p.m.', 2007, 4, 21, NULL, NULL, NULL, 'day', '21 April 2007', 34, 'https://en.wikipedia.org/wiki/2007_Ays%C3%A9n_Fjord_earthquakes'),
  ('Q4609417', '2007 Tocopilla earthquake', 'The 2007 Tocopilla earthquake occurred on November 14 at 12:40:50 local time. Its epicenter was located between Quillagua and Tocopilla, affecting the Tarapacá and the Antofagasta regions in northern Chile.', 2007, 11, 14, NULL, NULL, NULL, 'day', '14 November 2007', 39, 'https://en.wikipedia.org/wiki/2007_Tocopilla_earthquake'),
  ('Q151835', '2010 Chile earthquake', 'On 27 February 2010 at 03:34 UTC−03:00, a Mww 8.8 megathrust earthquake struck off the coast of the Maule Region of central Chile. One of the most powerful earthquakes ever recorded, it lasted approximately three minutes and was felt across six Chilean regions, home to roughly 80 percent of the country''s population.', 2010, 2, 27, NULL, NULL, NULL, 'day', '27 February 2010', 76, 'https://en.wikipedia.org/wiki/2010_Chile_earthquake'),
  ('Q842621', '2010 Pichilemu earthquakes', 'The 2010 Pichilemu earthquakes (Spanish: Terremoto de Pichilemu de 2010), also known as the Libertador O''Higgins earthquakes, were a pair of intraplate earthquakes measuring 6.9 and 7.0 Mw that struck Chile''s O''Higgins Region on 11 March 2010 about 16 minutes apart. The earthquakes were centred 15 kilometres (9.3 mi) northwest of the city of Pichilemu.', 2010, 3, 11, NULL, NULL, NULL, 'day', '11 March 2010', 62, 'https://en.wikipedia.org/wiki/2010_Pichilemu_earthquakes'),
  ('Q16004619', '2014 Iquique earthquake', 'The 2014 Iquique earthquake struck off the coast of Chile on 1 April, with a moment magnitude of 8.1–8.2, at 20:46 local time (23:46 UTC). The epicenter of the earthquake was approximately 95 kilometres (59 mi) northwest of Iquique.', 2014, 4, 1, NULL, NULL, NULL, 'day', '1 April 2014', 57, 'https://en.wikipedia.org/wiki/2014_Iquique_earthquake'),
  ('Q20978169', '2015 Illapel earthquake', 'The 2015 Illapel earthquake occurred 46 km (29 mi) offshore from Illapel (Coquimbo region, Chile) on 16 September 2015 at 19:54:32 Chile Standard Time (22:54:32 UTC), with a moment magnitude of 8.3–8.4. The initial quake lasted between three and five minutes; it was followed by several aftershocks greater than magnitude six and two that exceeded magnitude seven.', 2015, 9, 16, NULL, NULL, NULL, 'day', '16 September 2015', 64, 'https://en.wikipedia.org/wiki/2015_Illapel_earthquake'),
  ('Q28056528', '2016 Southern Chile earthquake', 'The 2016 Chiloé earthquake with a magnitude of Mww 7.6 struck 225 kilometres (140 mi) south-west of Puerto Montt in southern Chile at 11:22 local time, 25 December. The earthquake triggered a tsunami warning on coasts located up to 1,000 kilometres (620 mi) from the quake''s epicentre, generating massive evacuation across the Greater Chiloé Island, after advice from the Chilean government.', 2016, 12, 25, NULL, NULL, NULL, 'day', '25 December 2016', 39, 'https://en.wikipedia.org/wiki/2016_Chilo%C3%A9_earthquake'),
  ('Q60830232', '2019 Coquimbo earthquake', 'The 2019 Coquimbo earthquake occurred 10 km south southwest of Coquimbo in Chile, on January 19, 2019 at 22:32 (local time). The epicenter was located off the coast of the Coquimbo Region at a depth of 63.0 km,) and had a moment magnitude of 6.7.', 2019, 1, 19, NULL, NULL, NULL, 'day', '19 January 2019', 37, 'https://en.wikipedia.org/wiki/2019_Coquimbo_earthquake'),
  ('Q71500435', '2019–2021 Chilean protests', 'The estallido social (English: Social outburst) was a series of massive demonstrations and severe riots occurring mainly between October 2019 and March 2020, in response to a rise in fares on the Santiago Metro, a probity crisis, cost of living, university graduate unemployment, privatisation, and inequality prevalent in the country. It originated in Santiago and took place in all regions of Chile, with greater effect in the regional capitals.', 2019, 10, 14, 2020, NULL, NULL, 'day', '14 October 2019 – 2020', 64, 'https://en.wikipedia.org/wiki/Estallido_social'),
  ('Q78069997', '2019 Chilean Air Force C-130 accident', 'On 9 December 2019, a Chilean Air Force Lockheed C-130 Hercules military transport aircraft crashed in the Drake Passage while en route to Base Presidente Eduardo Frei Montalva, a Chilean military base on King George Island in Antarctica. The crash site was located on 12 December 2019 after a three-day search, and no survivors were found.', 2019, 12, 9, NULL, NULL, NULL, 'day', '9 December 2019', 45, 'https://en.wikipedia.org/wiki/2019_Chilean_Air_Force_C-130_crash'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q75072406', 'Chilean national plebiscite, 2020', 'A constitutional referendum was held in Chile on 25 October 2020. The referendum asked the citizens whether they wanted a new constitution to be drafted, and if so, whether it should be written by a constitutional convention made up of directly elected citizens or by a mixed convention that was composed of currently serving members of Parliament and half of directly elected citizens.', 2020, 10, 25, NULL, NULL, NULL, 'day', '25 October 2020', 48, 'https://en.wikipedia.org/wiki/2020_Chilean_constitutional_referendum');
